# Simple brute-force: check every possible rectangle
def find_all_rectangles_bruteforce(grid):
    colors = set()
    for row in grid:
        for cell in row:
            colors.add(cell)

    best = None
    best_area = 0

    for color in colors:
        if color == 0:
            continue

        for r_start in range(h):
            for r_end in range(r_start, h):
                for c_start in range(w):
                    for c_end in range(c_start, w):
                        # Check if all cells in this rectangle are the color
                        is_full = True
                        for rr in range(r_start, r_end + 1):
                            for cc in range(c_start, c_end + 1):
                                if grid[rr][cc] != color:
                                    is_full = False
                                    break
                            if not is_full:
                                break

                        if is_full:
                            area = (r_end - r_start + 1) * (c_end - c_start + 1)
                            if area > best_area:
                                best_area = area
                                best = (color, r_start, c_start, r_end - r_start + 1, c_end - c_start + 1, area)

    return best

